import {svg,scale,axes,series,palette,text,legend} from '../gallery-utils.js';
export function render({data,params:p}){const panels=[...new Set(data.map(d=>d.panel))],groups=[...new Set(data.map(d=>d.group))],c=palette(p);if(panels.length>6)throw Error('最多六个面板');if(!Number.isInteger(+p.columns))throw Error('面板列数必须为整数');const cols=Math.min(+p.columns,panels.length),rows=Math.ceil(panels.length/cols),cw=(p.width-125)/cols,ch=(p.height-50)/rows;if(cw<240||ch<190)throw Error('面板过密，请增大画布或减少列数');let s='';panels.forEach((name,i)=>{const d=data.filter(d=>d.panel===name),col=i%cols,row=Math.floor(i/cols),b={l:col*cw+70,r:(col+1)*cw-20,t:row*ch+65,b:(row+1)*ch-20};const x=scale(data.map(d=>d.x),b.l,b.r),y=scale((p.sharedY==='共享范围'?data:d).map(d=>d.y),b.b,b.t);s+=axes(b,x,y,{xLabel:'',yLabel:''})+text(b.l,b.t-13,`(${String.fromCharCode(97+i)}) ${name}`);groups.forEach((g,j)=>{const seriesRows=d.filter(d=>d.group===g).sort((a,b)=>a.x-b.x);if(seriesRows.length)s+=series(seriesRows,x,y,c[j%c.length],p);});});s+=text((p.width-125)/2,p.height-5,p.xLabel,'text-anchor="middle"')+text(15,52,p.yLabel)+legend({r:p.width-140,t:65},groups,c);return svg(p,s);}